import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Engines","description":"","frontmatter":{},"headers":[],"relativePath":"engines/index.md","filePath":"engines/index.md"}`),a={name:`engines/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="engines" tabindex="-1">Engines <a class="header-anchor" href="#engines" aria-label="Permalink to “Engines”">​</a></h1><p>Handl engines are <strong>pluggable implementations of the language operations</strong> — lex, parse, transform, typecheck and eval. A language definition is <em>data</em>; an engine interprets that data. Swapping an engine therefore changes how a language runs, not what it means.</p><p>Every operation follows the same shape: a small <strong>abstraction</strong> crate owns the contract (<code>§</code> marker type, request, trait, shared helpers) and one or more <strong>engine</strong> crates implement it. The kit decides which engine fills each slot.</p><h2 id="the-five-operations" tabindex="-1">The five operations <a class="header-anchor" href="#the-five-operations" aria-label="Permalink to “The five operations”">​</a></h2><table tabindex="0"><thead><tr><th>operation</th><th>contract</th><th>engines</th></tr></thead><tbody><tr><td>lex</td><td><a href="/docs/engine-lex/">engine-lex</a></td><td><a href="/docs/engine-lex-pattern/">engine-lex-pattern</a> — data-driven rules</td></tr><tr><td>parse</td><td><a href="/docs/engine-parse/">engine-parse</a></td><td><a href="/docs/engine-parse-pratt/">engine-parse-pratt</a> — Pratt, grammar rows</td></tr><tr><td>transform</td><td><a href="/docs/engine-transform/">engine-transform</a></td><td><a href="/docs/engine-transform-rewrite/">engine-transform-rewrite</a> — rule-interpreting</td></tr><tr><td>typecheck</td><td><a href="/docs/engine-typecheck/">engine-typecheck</a></td><td><code>engine-typecheck-nbe</code> (NBE; private) + bootstrap in the contract crate</td></tr><tr><td>eval</td><td><a href="/docs/engine-exec/">engine-exec</a></td><td><a href="/docs/engine-exec-tree-walk/">engine-exec-tree-walk</a> — reference; <a href="/docs/engine-exec-bytecode/">engine-exec-bytecode</a> — stack VM</td></tr></tbody></table><h2 id="shared-substrate" tabindex="-1">Shared substrate <a class="header-anchor" href="#shared-substrate" aria-label="Permalink to “Shared substrate”">​</a></h2><ul><li><a href="/docs/engine/">engine</a> — <code>Term</code>, <code>Model</code>, and the arena view every engine uses.</li></ul><h2 id="how-to-read-a-crate-here" tabindex="-1">How to read a crate here <a class="header-anchor" href="#how-to-read-a-crate-here" aria-label="Permalink to “How to read a crate here”">​</a></h2><p>Each engine repo publishes the same four quadrants: an <strong>overview</strong> (what it is), <strong>reference</strong> (the public API), <strong>how-to</strong> (task recipes) and <strong>explanation</strong> (why it is shaped that way). They carry no tutorials — end-to-end walkthroughs belong to the product that composes them, the <a href="/docs/handl/">Handl platform</a>.</p><h2 id="design-invariant" tabindex="-1">Design invariant <a class="header-anchor" href="#design-invariant" aria-label="Permalink to “Design invariant”">​</a></h2><p>The reference interpreter is the oracle: <code>engine-exec-bytecode</code> must produce results <strong>identical</strong> to <code>engine-exec-tree-walk</code>, and its conformance suite enforces that. Optimisation is allowed to change speed, never meaning. The same rule holds for the other operations — a data-driven engine must not become a second definition of the language.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};